import numpy as np

def dim_span(vectors):
    if len(vectors) == 0:
        return 0
    return int(np.linalg.matrix_rank(np.array(vectors, dtype=float)))

def extend_to_basis(vectors, n):
    out = [list(v) for v in vectors]
    if dim_span(out) < len(out):
        raise ValueError('the list is dependent')
    for j in range(n):
        e = [1 if i == j else 0 for i in range(n)]
        if dim_span(out + [e]) > len(out):
            out.append(e)
    return out
